### Approach 4: File Upload Validation

**Overview:** Validate file uploads comprehensively including filename sanitization, content type verification, file size limits, and virus scanning.

**Implementation:**

```csharp
[HttpPost("upload")]
public async Task<IActionResult> UploadDocument(
    IFormFile file,
    [FromForm] string documentType)
{
    // 1. Input validation
    var allowedDocTypes = new[] { "claims", "eligibility", "enrollment", "correspondence" };
    if (!allowedDocTypes.Contains(documentType))
        return BadRequest("Invalid document type");

    if (file == null || file.Length == 0)
        return BadRequest("No file provided");

    // 2. File size validation (10 MB limit)
    if (file.Length > 10 * 1024 * 1024)
        return BadRequest("File size exceeds 10 MB limit");

    // 3. Content type validation (allow-list)
    var allowedContentTypes = new[] { "application/pdf", "image/jpeg", "image/png" };
    if (!allowedContentTypes.Contains(file.ContentType))
        return BadRequest($"File type {file.ContentType} not allowed");

    // 4. Filename sanitization (prevent path traversal)
    string sanitizedFilename = Path.GetFileName(file.FileName);
    sanitizedFilename = Regex.Replace(sanitizedFilename, @"[^a-zA-Z0-9\-_\.]", "_");

    // 5. Generate unique filename (prevent overwrites)
    string uniqueFilename = $"{Guid.NewGuid()}_{sanitizedFilename}";

    // 6. Construct safe file path (no user input in directory path)
    string uploadDirectory = Path.Combine(_uploadBasePath, documentType);
    Directory.CreateDirectory(uploadDirectory);  // Ensure directory exists

    string filePath = Path.Combine(uploadDirectory, uniqueFilename);

    // 7. Virus scan before saving
    using (var stream = file.OpenReadStream())
    {
        var scanResult = await _antivirusService.ScanAsync(stream);
        if (!scanResult.IsClean)
            return BadRequest("File failed security scan");
    }

    // 8. Save file
    using (var stream = new FileStream(filePath, FileMode.Create))
    {
        await file.CopyToAsync(stream);
    }

    // 9. Return sanitized response (don't expose internal file paths)
    return Ok(new { documentId = uniqueFilename, documentType });
}
```

