[patterns/application/api-microservices/PTN-APP-API-019-input-validation-pattern.md#approach-5-cross-field-business-rule-validation]

### Approach 5: Cross-Field Business Rule Validation

**Overview:** Implement business rule validation ensuring logical consistency across multiple fields beyond individual field format checks.

**Implementation:**

```csharp
// FluentValidation - Comprehensive Business Rules
public class ClaimValidator : AbstractValidator<ClaimSubmissionRequest>
{
    public ClaimValidator()
    {
        // 1. Individual field validation
        RuleFor(x => x.ClaimId)
            .NotEmpty()
            .Matches(@"^CLM-[0-9]{4}-[0-9]{5}$")
            .WithMessage("Claim ID must match format CLM-YYYY-NNNNN");

        RuleFor(x => x.ProviderId)
            .NotEmpty()
            .Matches(@"^[0-9]{10}$")
            .WithMessage("Provider ID must be 10-digit NPI");

        RuleFor(x => x.BeneficiaryId)
            .NotEmpty()
            .Matches(@"^[0-9]{9}$")
            .WithMessage("Beneficiary ID must be 9 digits");

        RuleFor(x => x.ServiceDate)
            .NotEmpty()
            .Must(BeValidDate)
            .WithMessage("Service date must be valid date");

        RuleFor(x => x.SubmissionDate)
            .NotEmpty()
            .Must(BeValidDate)
            .WithMessage("Submission date must be valid date");

        // 2. Cross-field business rules
        RuleFor(x => x)
            .Must(x => x.SubmissionDate >= x.ServiceDate)
            .WithMessage("Submission date cannot be before service date")
            .When(x => x.ServiceDate != default && x.SubmissionDate != default);

        RuleFor(x => x)
            .Must(x => (x.SubmissionDate - x.ServiceDate).Days <= 180)
            .WithMessage("Claims must be submitted within 180 days of service date")
            .When(x => x.ServiceDate != default && x.SubmissionDate != default);

        RuleFor(x => x.PaidAmount)
            .InclusiveBetween(0.01m, 999999.99m)
            .WithMessage("Paid amount must be between $0.01 and $999,999.99");

        RuleFor(x => x)
            .Must(x => x.PaidAmount <= x.BilledAmount)
            .WithMessage("Paid amount cannot exceed billed amount")
            .When(x => x.PaidAmount > 0 && x.BilledAmount > 0);

        // 3. State-specific rules
        RuleFor(x => x)
            .Must(x => ValidateStateSpecificRules(x))
            .WithMessage("Claim violates state-specific business rules");
    }

    private bool BeValidDate(DateTime date)
    {
        return date != default && date >= new DateTime(2000, 1, 1) && date <= DateTime.Today;
    }

    private bool ValidateStateSpecificRules(ClaimSubmissionRequest claim)
    {
        // Load state-specific configuration
        var stateConfig = _stateConfigService.GetStateConfig(claim.StateCode);

        // Validate submission deadline
        var daysSinceService = (claim.SubmissionDate - claim.ServiceDate).Days;
        if (daysSinceService > stateConfig.MaxSubmissionDays)
            return false;

        // Validate prior authorization if required
        if (stateConfig.RequiresPriorAuth(claim.ProcedureCode) &&
            string.IsNullOrEmpty(claim.PriorAuthNumber))
            return false;

        return true;
    }
}

// Controller integration
[HttpPost]
public async Task<IActionResult> SubmitClaim([FromBody] ClaimSubmissionRequest request)
{
    var validator = new ClaimValidator();
    var validationResult = await validator.ValidateAsync(request);

    if (!validationResult.IsValid)
    {
        var problemDetails = new ValidationProblemDetails();
        foreach (var error in validationResult.Errors)
        {
            problemDetails.Errors.Add(error.PropertyName, new[] { error.ErrorMessage });
        }

        return BadRequest(problemDetails);
    }

    // Process validated claim
    await _claimService.SubmitAsync(request);
    return Ok();
}
```

