##### Basic Member Request (strict mode)

```typescript
import { z } from 'zod';
import { Request, Response, NextFunction } from 'express';

// .strict() rejects any key not declared in the schema,
// preventing __proto__, constructor, and prototype injection
const CreateMemberSchema = z
  .object({
    memberId: z.string().uuid(),
    dateOfBirth: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
    planCode: z.string().min(1).max(20).regex(/^[A-Z0-9-]+$/),
    stateCode: z.string().length(2).regex(/^[A-Z]{2}$/),
  })
  .strict();

type CreateMemberRequest = z.infer<typeof CreateMemberSchema>;

export function validateCreateMember(
  req: Request,
  res: Response,
  next: NextFunction,
): void {
  const result = CreateMemberSchema.safeParse(req.body);
  if (!result.success) {
    res.status(400).json({
      type: 'https://api.gainwelltechnologies.com/problems/validation-error',
      title: 'One or more validation errors occurred',
      status: 400,
      errors: result.error.flatten().fieldErrors,
    });
    return;
  }
  // result.data contains only the validated, typed fields — prototype-safe
  req.validatedBody = result.data;
  next();
}
```

