##### Claim Submission with Cross-Field Business Rule Validation

```typescript
import { z } from 'zod';

const ClaimSubmissionSchema = z
  .object({
    claimId: z.string().regex(/^CLM-\d{4}-\d{5}$/),
    providerId: z.string().regex(/^\d{10}$/),
    beneficiaryId: z.string().regex(/^\d{9}$/),
    serviceDate: z.string().datetime({ offset: false }),
    submissionDate: z.string().datetime({ offset: false }),
    billedAmount: z.number().positive().max(999999.99),
    paidAmount: z.number().min(0).max(999999.99),
    procedureCode: z.string().regex(/^[A-Z0-9]{5}$/),
  })
  .strict()
  // Cross-field rule: submission cannot precede service
  .refine(
    (data) => new Date(data.submissionDate) >= new Date(data.serviceDate),
    {
      message: 'submissionDate must be on or after serviceDate',
      path: ['submissionDate'],
    },
  )
  // Cross-field rule: paid cannot exceed billed
  .refine((data) => data.paidAmount <= data.billedAmount, {
    message: 'paidAmount cannot exceed billedAmount',
    path: ['paidAmount'],
  });

type ClaimSubmissionRequest = z.infer<typeof ClaimSubmissionSchema>;
```

