[patterns/application/api-microservices/PTN-APP-API-019-input-validation-pattern.md#query-parameter-validation-type-coercion]

##### Query Parameter Validation (type coercion)

Query parameters arrive as strings. Use `z.coerce` to convert to the expected type safely, rather than relying on implicit JavaScript coercion:

```typescript
const EligibilityQuerySchema = z
  .object({
    beneficiaryId: z.string().regex(/^\d{9}$/),
    serviceDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
    stateCode: z.string().length(2).regex(/^[A-Z]{2}$/),
    pageSize: z.coerce.number().int().min(1).max(100).default(25),
    pageToken: z.string().max(256).optional(),
  })
  .strict();

export function validateEligibilityQuery(
  req: Request,
  res: Response,
  next: NextFunction,
): void {
  const result = EligibilityQuerySchema.safeParse(req.query);
  if (!result.success) {
    res.status(400).json({
      type: 'https://api.gainwelltechnologies.com/problems/validation-error',
      title: 'Invalid query parameters',
      status: 400,
      errors: result.error.flatten().fieldErrors,
    });
    return;
  }
  req.validatedQuery = result.data;
  next();
}
```

